const fs=require('node:fs'),path=require('node:path');const ROOT=process.env.LOBOS_ROOT||path.resolve(__dirname,'..');const DIR=process.env.M2_ROOTFS_DIR||path.join(ROOT,'work/rootfs');const WORK=path.join(DIR,'workdir');//  => 而那**可写层**逐字**要**那 tmpfs **挂载点****在**、=> 而而那**它**逐字**是**那**一个**目录**。
if(!fs.existsSync(WORK)){console.error('那可写层逐字**不在** '+WORK+'（=> 而那 rootfs 那一件逐字**还不存在**、=> 而按 C-105 报缺）');process.exit(1);}if(!fs.statSync(WORK).isDirectory()){console.error('那可写层逐字**不是**那**一个**目录（=> 而那 tmpfs 挂载点逐字**是**那**目录**）');process.exit(1);}//  => 而那**可写**的**判据**：=> 而那**它**逐字**要**那**目录**逐字**能**写**。
const probe=path.join(WORK,'.lobos-write-probe-'+process.pid);let wrote=false;try{fs.writeFileSync(probe,'probe');wrote=fs.existsSync(probe);}catch(e){console.error('那工作区逐字**写不进去**：'+String(e.message||e));process.exit(1);}finally{try{fs.unlinkSync(probe);}catch(e){}}if(!wrote){console.error('那工作区逐字**写不进去**（=> 而那一格逐字**要**那**可写**）');process.exit(1);}const SH=path.join(DIR,'rootfs-shape.json');if(!fs.existsSync(SH)){console.error('那形状说明逐字**不在** '+SH+'（=> 而按 C-105 报缺）');process.exit(1);}const sh=JSON.parse(fs.readFileSync(SH,'utf8'));if(!sh.writableLayer||sh.writableLayer.kind!=='tmpfs'){console.error('那形状说明逐字**那可写层**逐字**不**是**那 tmpfs 那一族（=> 而按 C-105 报缺）');process.exit(1);}console.log('ROOTFS_WRITABLE_OK workdir='+WORK+' kind=tmpfs');
